n0:createOracleTrigger.n0:source:
CREATE OR REPLACE EDITIONABLE TRIGGER "%USER_NAME%"."TRG_SESSIONS_AUDIT" 
BEFORE INSERT OR UPDATE
ON PEDS_MSTR.SESSIONS
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN
            -- For INSERT operations
            IF INSERTING THEN
                :NEW.created_by := COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER);
                :NEW.created_on := ET_SYSDATE;
                :NEW.updated_by := COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER);
                :NEW.updated_on := ET_SYSDATE;
                :NEW.row_version := 1;
            END IF;

            -- For UPDATE operations
            IF UPDATING THEN
                -- Preserve original created values
                :NEW.created_by := :OLD.created_by;
                :NEW.created_on := :OLD.created_on;
                -- Update the modified values
                :NEW.updated_by := COALESCE(SYS_CONTEXT('APEX$SESSION','APP_USER'), USER);
                :NEW.updated_on := ET_SYSDATE;
                :NEW.row_version := NVL(:OLD.row_version, 0) + 1;
            END IF;
        END;
/
